-- TF2025 历史销售事件批量重配回滚（2026-11-21）
-- 回滚前应确认目标销售与设备仍无新业务关联。
START TRANSACTION;
CREATE TEMPORARY TABLE tf2025_sale_event_reassign_batch_20261121_rollback (target_sale_id BIGINT NOT NULL PRIMARY KEY,target_device_id BIGINT NOT NULL,serial_number VARCHAR(100) NOT NULL,new_customer_id BIGINT NOT NULL,new_sale_time DATETIME NOT NULL,new_sale_price DECIMAL(10,2) NOT NULL,new_invoice_number VARCHAR(100) NOT NULL,old_customer_id BIGINT NOT NULL,old_sale_time DATETIME NOT NULL,old_sale_price DECIMAL(10,2) NOT NULL,old_invoice_number VARCHAR(100) NOT NULL,old_device_sale_time DATETIME NULL,old_device_sale_price DECIMAL(10,2) NULL,old_device_is_new TINYINT NULL,old_inventory_time DATETIME NULL,old_brand_id INT NULL,old_model_id INT NULL,old_color_id INT NULL,old_memory_id INT NULL,old_sale_remarks TEXT NULL,old_device_remarks TEXT NULL);
SET @rollback_precheck_passed := 1;
SELECT @rollback_precheck_passed := IF(COUNT(*)=484,@rollback_precheck_passed,0) FROM tf2025_sale_event_reassign_batch_20261121_rollback b JOIN sales s ON s.id=b.target_sale_id JOIN phones p ON p.id=s.phone_id AND p.id=b.target_device_id WHERE BINARY p.serial_number=BINARY b.serial_number AND s.customer_id=b.new_customer_id AND s.sale_time=b.new_sale_time AND s.sale_price=b.new_sale_price AND BINARY s.invoice_number=BINARY b.new_invoice_number AND p.sale_time=b.new_sale_time AND p.sale_price=b.new_sale_price AND p.is_new=0 AND p.inventory_time IS NOT NULL;
SELECT @rollback_precheck_passed := IF(COUNT(*)=0,@rollback_precheck_passed,0) FROM national_subsidies n JOIN tf2025_sale_event_reassign_batch_20261121_rollback b ON n.sale_id=b.target_sale_id OR n.phone_id=b.target_device_id;
SELECT @rollback_precheck_passed := IF(COUNT(*)=0,@rollback_precheck_passed,0) FROM payment_records n JOIN tf2025_sale_event_reassign_batch_20261121_rollback b ON n.order_id=b.target_sale_id OR n.sales_order_id=b.target_sale_id;
SELECT @rollback_precheck_passed := IF(COUNT(*)=0,@rollback_precheck_passed,0) FROM sales_order_items n JOIN tf2025_sale_event_reassign_batch_20261121_rollback b ON n.sale_id=b.target_sale_id OR n.phone_id=b.target_device_id OR n.linked_phone_sale_id=b.target_sale_id;
SELECT @rollback_precheck_passed := IF(COUNT(*)=0,@rollback_precheck_passed,0) FROM repairs n JOIN tf2025_sale_event_reassign_batch_20261121_rollback b ON n.phone_id=b.target_device_id;
SELECT @rollback_precheck_passed AS rollback_precheck_passed;
UPDATE sales s JOIN tf2025_sale_event_reassign_batch_20261121_rollback b ON b.target_sale_id=s.id SET s.customer_id=b.old_customer_id,s.sale_time=b.old_sale_time,s.sale_price=b.old_sale_price,s.invoice_number=b.old_invoice_number,s.remarks=b.old_sale_remarks,s.updated_at=NOW() WHERE @rollback_precheck_passed=1;
UPDATE phones p JOIN tf2025_sale_event_reassign_batch_20261121_rollback b ON b.target_device_id=p.id SET p.sale_price=b.old_device_sale_price,p.sale_time=b.old_device_sale_time,p.inventory_time=b.old_inventory_time,p.is_new=b.old_device_is_new,p.brand_id=b.old_brand_id,p.model_id=b.old_model_id,p.color_id=b.old_color_id,p.memory_id=b.old_memory_id,p.remarks=b.old_device_remarks WHERE @rollback_precheck_passed=1;
SELECT @rollback_precheck_passed AS rollback_precheck_passed;
SELECT COUNT(*) AS restored_sales FROM sales s JOIN tf2025_sale_event_reassign_batch_20261121_rollback b ON b.target_sale_id=s.id AND s.customer_id=b.old_customer_id AND s.sale_time=b.old_sale_time AND s.sale_price=b.old_sale_price AND BINARY s.invoice_number=BINARY b.old_invoice_number;
SELECT COUNT(*) AS restored_devices FROM phones p JOIN tf2025_sale_event_reassign_batch_20261121_rollback b ON b.target_device_id=p.id AND p.sale_time=b.old_device_sale_time AND p.inventory_time <=> b.old_inventory_time AND p.sale_price <=> b.old_device_sale_price AND p.is_new <=> b.old_device_is_new;
-- 由执行器确认 rollback_precheck_passed=1、restored_sales=484、restored_devices=484 后 COMMIT，否则 ROLLBACK。
